import{_ as s,C as r,o as n,c as d,j as a,a as c,E as i,ak as l}from"./chunks/framework.CK0KoRlj.js";const b=JSON.parse('{"title":"Read-only MCP servers for SQL Server and PostgreSQL","description":"mssql-mcp-go and postgres-mcp-go give AI assistants structured, read-only access to two of the most common relational databases.","frontmatter":{"title":"Read-only MCP servers for SQL Server and PostgreSQL","description":"mssql-mcp-go and postgres-mcp-go give AI assistants structured, read-only access to two of the most common relational databases.","author":"vinaykumar","date":"2026-10-08T00:00:00.000Z","tags":["mcp","databases","go"],"outline":"deep","editLink":false},"headers":[],"relativePath":"blog/read-only-mcp-servers.md","filePath":"blog/read-only-mcp-servers.md"}'),p={name:"blog/read-only-mcp-servers.md"};function h(t,e,m,g,u,f){const o=r("AuthorCard");return n(),d("div",null,[e[0]||(e[0]=a("h1",{id:"read-only-mcp-servers-for-sql-server-and-postgresql",tabindex:"-1"},[c("Read-only MCP servers for SQL Server and PostgreSQL "),a("a",{class:"header-anchor",href:"#read-only-mcp-servers-for-sql-server-and-postgresql","aria-label":'Permalink to "Read-only MCP servers for SQL Server and PostgreSQL"'},"​")],-1)),i(o,{author:t.$frontmatter.author},null,8,["author"]),e[1]||(e[1]=l('<p><code>mssql-mcp-go</code> and <code>postgres-mcp-go</code> are <a href="https://modelcontextprotocol.io" target="_blank" rel="noreferrer">Model Context Protocol</a> servers written in Go. They expose database metadata and analysis to AI assistants without giving those assistants a way to change data.</p><h2 id="read-only-by-design" tabindex="-1">Read-only by design <a class="header-anchor" href="#read-only-by-design" aria-label="Permalink to &quot;Read-only by design&quot;">​</a></h2><p>Both servers validate every query before it runs. INSERT, UPDATE, DELETE, DROP, and other mutating statements are rejected, and stored procedures are analysed rather than executed. That constraint is the product, not a setting: an assistant answering a question about a schema should not be able to truncate a table by accident.</p><h2 id="the-same-toolset-two-dialects" tabindex="-1">The same toolset, two dialects <a class="header-anchor" href="#the-same-toolset-two-dialects" aria-label="Permalink to &quot;The same toolset, two dialects&quot;">​</a></h2><p>Each server exposes more than 70 tools grouped by what they help you do: schema discovery, data profiling, performance analysis, security auditing, migration assessment, and monitoring. The names and groups are consistent across both servers, but the SQL dialect is not. A T-SQL snippet does not transfer to PostgreSQL, and the documentation keeps the two reference pages separate for that reason.</p><p><code>mssql-mcp-go</code> adds SQL Server specific features such as Always Encrypted column decryption with local PFX certificates. <code>postgres-mcp-go</code> uses <code>POSTGRES_*</code> variables and PostgreSQL-specific options such as <code>ssl_mode</code> and <code>search_path</code>.</p><h2 id="connecting-a-client" tabindex="-1">Connecting a client <a class="header-anchor" href="#connecting-a-client" aria-label="Permalink to &quot;Connecting a client&quot;">​</a></h2><p>The default transport is <code>stdio</code>, so an MCP client launches the binary instead of connecting to a port. The servers are available from Homebrew, as release binaries for Linux, macOS, and Windows, and as multi-arch container images.</p><p>Start with the <a href="/docs/mssql-mcp-go/">mssql-mcp-go documentation</a> or the <a href="/docs/postgres-mcp-go/">postgres-mcp-go documentation</a>. Both projects are MIT licensed.</p>',9))])}const v=s(p,[["render",h]]);export{b as __pageData,v as default};
